css:
.d-ftd{position:relative;width:300px;max-width:100%;height:150px;border:1px solid var(--line);border-radius:2px;background:var(--paper);overflow:hidden;font-family:var(--sans)}
.d-ftd-page{padding:12px}
.d-ftd-line{max-width:200px;margin:0 0 10px;font-size:11px;line-height:1.7;color:var(--muted)}
.d-ftd-open{font-family:var(--mono);font-size:9px;letter-spacing:.08em;padding:5px 9px;border:1px solid var(--line);border-radius:2px;background:var(--paper);color:var(--ink);cursor:pointer;transition:border-color 120ms steps(6)}
.d-ftd-open:hover{border-color:var(--ink)}
.d-ftd-open:focus-visible{outline:1px solid var(--ink);outline-offset:2px}
.d-ftd-scrim{position:absolute;inset:0;background:var(--bg);opacity:.72}
.d-ftd-box{position:absolute;left:14px;right:14px;top:16px;padding:10px 12px 12px;border:1px solid var(--ink);border-radius:2px;background:var(--paper);box-shadow:0 12px 24px -8px #20241e26}
.d-ftd.is-open .d-ftd-box{animation:d-focus-trap-dialog-snap 120ms steps(6) both}
@keyframes d-focus-trap-dialog-snap{from{transform:translateY(6px)}to{transform:translateY(0)}}
.d-ftd-title{display:block;font-size:11px;line-height:1.5;font-weight:650;color:var(--ink)}
.d-ftd-row{display:flex;gap:6px;margin-top:8px}
.d-ftd-opt{width:52px;padding:4px 0;border:1px solid var(--line);border-radius:2px;background:var(--paper);font-family:var(--mono);font-size:9px;color:var(--muted);cursor:pointer;transition:border-color 120ms steps(6),color 120ms steps(6),background-color 120ms steps(6)}
.d-ftd-opt.is-on{border-color:var(--ink);background:var(--bg);color:var(--ink)}
.d-ftd-opt:focus-visible{outline:1px solid #2b4b8f;outline-offset:2px}
.d-ftd-caret{--i:0;display:block;width:52px;height:1px;margin-top:4px;background:#2b4b8f;transform:translateX(calc(var(--i,0) * 58px));transition:transform 120ms steps(6)}
.d-ftd-hint{display:block;margin-top:8px;font-family:var(--mono);font-size:9px;letter-spacing:.08em;color:var(--faint)}

init:
root => {
  const stage = root.querySelector('.d-ftd');
  if (!stage || stage.dataset.ftd) return;
  stage.dataset.ftd = '1';
  const openBtn = stage.querySelector('.d-ftd-open');
  const box = stage.querySelector('.d-ftd-box');
  const scrim = stage.querySelector('.d-ftd-scrim');
  const caret = stage.querySelector('.d-ftd-caret');
  const opts = Array.from(stage.querySelectorAll('.d-ftd-opt'));
  const mark = el => {
    const i = opts.indexOf(el);
    opts.forEach(o => o.classList.toggle('is-on', o === el));
    caret.style.setProperty('--i', String(i < 0 ? 0 : i));
  };
  const open = () => {
    stage.classList.add('is-open');
    box.hidden = false;
    scrim.hidden = false;
    opts[0].focus();
    mark(opts[0]);
  };
  const close = () => {
    stage.classList.remove('is-open');
    box.hidden = true;
    scrim.hidden = true;
    openBtn.focus();
  };
  openBtn.addEventListener('click', open);
  scrim.addEventListener('click', close);
  opts.forEach(o => {
    o.addEventListener('focus', () => mark(o));
    o.addEventListener('click', close);
  });
  box.addEventListener('keydown', e => {
    if (e.key === 'Escape') { e.preventDefault(); close(); return; }
    if (e.key !== 'Tab' || opts.length < 2) return;
    const first = opts[0], last = opts[opts.length - 1];
    if (e.shiftKey && stage.contains(document.activeElement) && document.activeElement === first) { e.preventDefault(); last.focus(); }
    else if (!e.shiftKey && document.activeElement === last) { e.preventDefault(); first.focus(); }
  });
}
